import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const card = new THREE.Group();
  card.position.set(0, 0, 0);

  // Design tokens
  const colors = {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  const cardWidth = 2.4;
  const cardHeight = 3.2;
  const cornerRadius = 0.06;
  const padding = 0.5;
  const headerHeight = 0.08;
  const featureRowHeight = 0.375;

  // Background plane
  const bgGeometry = new THREE.PlaneGeometry(cardWidth, cardHeight);
  const bgMaterial = new THREE.MeshBasicNodeMaterial({
    color: new THREE.Color(colors.surface)
  });
  const bgPlane = new THREE.Mesh(bgGeometry, bgMaterial);
  bgPlane.position.z = 0;
  card.add(bgPlane);

  // Border plane (hairline)
  const borderGeometry = new THREE.PlaneGeometry(
    cardWidth + 0.012,
    cardHeight + 0.012
  );
  const borderMaterial = new THREE.MeshBasicNodeMaterial({
    color: new THREE.Color('#2a2a33')
  });
  const borderPlane = new THREE.Mesh(borderGeometry, borderMaterial);
  borderPlane.position.z = -0.001;
  card.add(borderPlane);

  // Machined header strip
  const headerGeometry = new THREE.PlaneGeometry(cardWidth, headerHeight);
  const headerMaterial = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color(colors.surface),
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.1
  });
  const headerPlane = new THREE.Mesh(headerGeometry, headerMaterial);
  headerPlane.position.y = cardHeight / 2 - headerHeight / 2;
  headerPlane.position.z = 0.001;
  card.add(headerPlane);

  // Feature hairlines
  const hairlineColor = new THREE.Color('#23232b');
  for (let i = 0; i < 3; i++) {
    const lineGeometry = new THREE.PlaneGeometry(
      cardWidth - 2 * padding,
      0.006
    );
    const lineMaterial = new THREE.MeshBasicNodeMaterial({
      color: hairlineColor
    });
    const line = new THREE.Mesh(lineGeometry, lineMaterial);
    const yOffset =
      cardHeight / 2 -
      headerHeight -
      padding -
      featureRowHeight * (i + 1);
    line.position.y = yOffset;
    line.position.z = 0.001;
    card.add(line);
  }

  // CTA button plane with gradient approximation
  const ctaWidth = 1.4;
  const ctaHeight = 0.36;
  const ctaGeometry = new THREE.PlaneGeometry(ctaWidth, ctaHeight);
  const ctaMaterial = new THREE.MeshBasicNodeMaterial({
    color: new THREE.Color('#c1121f'),
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.5
  });
  const ctaPlane = new THREE.Mesh(ctaGeometry, ctaMaterial);
  const ctaYPos = -(cardHeight / 2) + 0.5 + ctaHeight / 2;
  ctaPlane.position.y = ctaYPos;
  ctaPlane.position.z = 0.002;
  card.add(ctaPlane);

  // Render text via fontAtlas
  const textSpecs = [
    {
      content: 'ATELIER RESERVE',
      family: 'JetBrains Mono',
      fontSize: 20,
      fontWeight: 700,
      x: -cardWidth / 2 + padding,
      y: cardHeight / 2 - headerHeight - padding * 0.5,
      color: colors.paper
    },
    {
      content: '$480',
      family: 'Lora',
      fontSize: 62,
      fontWeight: 600,
      x: 0,
      y: cardHeight / 2 - headerHeight - padding - 0.35,
      color: colors.accent
    },
    {
      content: 'PER MONTH, BILLED ANNUALLY',
      family: 'JetBrains Mono',
      fontSize: 9,
      fontWeight: 400,
      x: 0,
      y: cardHeight / 2 - headerHeight - padding - 0.65,
      color: colors.paper
    },
    {
      content: 'Quarterly movement service',
      family: 'JetBrains Mono',
      fontSize: 13,
      fontWeight: 400,
      x: -cardWidth / 2 + padding,
      y: cardHeight / 2 - headerHeight - padding - 1.0,
      color: colors.paper,
      isFeature: true
    },
    {
      content: 'Priority commission slots',
      family: 'JetBrains Mono',
      fontSize: 13,
      fontWeight: 400,
      x: -cardWidth / 2 + padding,
      y: cardHeight / 2 - headerHeight - padding - 1.375,
      color: colors.paper,
      isFeature: true
    },
    {
      content: 'Private fitting lounge access',
      family: 'JetBrains Mono',
      fontSize: 13,
      fontWeight: 400,
      x: -cardWidth / 2 + padding,
      y: cardHeight / 2 - headerHeight - padding - 1.75,
      color: colors.paper,
      isFeature: true
    },
    {
      content: 'Lifetime case refinishing',
      family: 'JetBrains Mono',
      fontSize: 13,
      fontWeight: 400,
      x: -cardWidth / 2 + padding,
      y: cardHeight / 2 - headerHeight - padding - 2.125,
      color: colors.paper,
      isFeature: true
    },
    {
      content: 'JOIN THE RESERVE',
      family: 'JetBrains Mono',
      fontSize: 13,
      fontWeight: 700,
      x: 0,
      y: ctaYPos,
      color: colors.ink
    }
  ];

  const featureMeshes = [];

  textSpecs.forEach((spec) => {
    if (ctx.fontAtlas && typeof ctx.fontAtlas.createText === 'function') {
      const textMesh = ctx.fontAtlas.createText(spec.content, {
        fontSize: spec.fontSize,
        fontFamily: spec.family,
        fontWeight: spec.fontWeight,
        color: spec.color
      });

      if (textMesh) {
        textMesh.position.set(spec.x, spec.y, 0.003);
        card.add(textMesh);

        if (spec.isFeature) {
          featureMeshes.push(textMesh);
          textMesh.userData.isFeature = true;
        }
      }
    }
  });

  // Animations timeline storage
  const timelines = [];

  // Weighted settle: card mount scale 1.04 -> 1.0
  card.scale.set(1.04, 1.04, 1);
  const settleTimeline = gsap.to(card.scale, {
    x: 1,
    y: 1,
    duration: 0.9,
    ease: 'power4.out'
  });
  timelines.push(settleTimeline);

  // Stagger fade-up for feature rows
  const featureAnimState = featureMeshes.map((mesh) => {
    const origY = mesh.position.y;
    mesh.position.y += 0.2;
    return { mesh, origY };
  });

  if (featureAnimState.length > 0) {
    const featureTimeline = gsap.timeline();
    featureAnimState.forEach((item, idx) => {
      featureTimeline.to(
        item.mesh.position,
        {
          y: item.origY,
          duration: 0.5,
          ease: 'power2.out'
        },
        idx * 0.08
      );
    });
    timelines.push(featureTimeline);
  }

  // CTA press animation handler
  let ctaTimeline = null;
  card.userData.handlers = {
    ctaPress: () => {
      if (ctaTimeline) ctaTimeline.kill();
      ctaTimeline = gsap.to(ctaPlane.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
        yoyo: true,
        repeat: 1
      });
      timelines.push(ctaTimeline);
    }
  };

  ctaPlane.userData.interactive = true;
  ctaPlane.userData.onPointerDown = () => {
    card.userData.handlers.ctaPress();
  };

  // Cleanup function
  card.userData.cleanup = () => {
    // Kill all GSAP timelines
    timelines.forEach((tl) => {
      if (tl && typeof tl.kill === 'function') {
        tl.kill();
      }
    });
    if (ctaTimeline) ctaTimeline.kill();

    // Dispose geometries and materials
    card.traverse((node) => {
      if (node instanceof THREE.Mesh) {
        if (node.geometry) {
          node.geometry.dispose();
        }
        if (node.material) {
          if (Array.isArray(node.material)) {
            node.material.forEach((mat) => {
              if (mat && typeof mat.dispose === 'function') {
                mat.dispose();
              }
            });
          } else if (typeof node.material.dispose === 'function') {
            node.material.dispose();
          }
        }
      }
    });
  };

  return card;
}
